/**
 * Offline shell for Herd OS.
 *
 * Strategy:
 *  - Navigations: network-first, fall back to the cached shell. The parlor loses
 *    signal constantly; the app must still open.
 *  - Static assets: stale-while-revalidate.
 *  - Everything else (API/Firestore): left alone — the Firestore SDK has its own
 *    IndexedDB persistence and conflict resolution, which is better than ours.
 */

// Build-time precache manifest (generated by scripts/precache-manifest.mjs after
// every `next build`). It lists every hashed JS/CSS chunk so the whole app can
// cold-start offline — not just pages visited once online. Absent in dev, where
// the service worker doesn't register anyway.
try {
  importScripts("/precache.js");
} catch {
  /* no manifest yet (dev / first run) — fall back to the shell + runtime cache */
}

const BUILD = self.__BUILD || "v1";
const VERSION = "herdos-" + BUILD;
// Every static route's document, so a cold hard-navigation to any screen renders
// the right page offline — not the dashboard fallback. Fetched once at install
// while online. (Dynamic routes like /animals/[id] can't be precached; they fall
// back to the shell and the client router takes over.)
const SHELL = [
  "/", "/dashboard", "/animals", "/calves", "/breeding", "/health",
  "/milk", "/feed", "/tasks", "/inventory", "/finance", "/partners",
  "/reports", "/analytics", "/assistant", "/notifications", "/settings", "/map",
  "/manifest.webmanifest", "/icon.svg", "/icon-192.png", "/icon-512.png",
];
const PRECACHE = [...SHELL, ...(self.__PRECACHE || [])];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(VERSION).then((cache) =>
      // Add individually: cache.addAll is atomic, so one 404 would abort the
      // whole precache. A single missing asset must not sink offline support.
      Promise.all(PRECACHE.map((url) => cache.add(url).catch(() => undefined))),
    ),
  );
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)))),
  );
  self.clients.claim();
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(VERSION).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(() => caches.match(request).then((hit) => hit ?? caches.match("/dashboard"))),
    );
    return;
  }

  if (/\.(css|js|woff2?|png|svg|jpg|webp)$/.test(url.pathname) || url.pathname.startsWith("/_next/")) {
    event.respondWith(
      caches.match(request).then((cached) => {
        const network = fetch(request)
          .then((response) => {
            const copy = response.clone();
            caches.open(VERSION).then((cache) => cache.put(request, copy));
            return response;
          })
          .catch(() => cached);
        return cached ?? network;
      }),
    );
  }
});

/** Push notifications — vaccination due, calving imminent, tank temperature alarm. */
self.addEventListener("push", (event) => {
  if (!event.data) return;
  const payload = event.data.json();
  event.waitUntil(
    self.registration.showNotification(payload.title ?? "Herd OS", {
      body: payload.body,
      icon: "/icon.svg",
      badge: "/icon.svg",
      data: { href: payload.href ?? "/dashboard" },
      tag: payload.tag,
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  event.waitUntil(self.clients.openWindow(event.notification.data?.href ?? "/dashboard"));
});
